            aOrbiterK = ((aWandererC + RotL64(aCross, 51U)) + 0xAD9A9CBD74C630FEULL) + aTwistOrbiterAssignSaltB[(((255U - aIndex) + 184U)) & S_SALT1];
            aOrbiterF = ((aWandererK + RotL64(aIngress, 18U)) + 0x5301B39DCBE0C9ACULL) + aTwistOrbiterAssignSaltD[((aIndex + 3U)) & S_SALT1];
