            aOrbiterH = (aOrbiterH ^ aOrbiterK) ^ 0x919315892C29A512ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xB328B272FA6A8AB3ULL), 27U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterG) + 0x9E29BAA7C9C55542ULL) + aTwistOrbiterUpdateSaltB[(((255U - aIndex) + 191U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0x1F7A688E528CD030ULL;
