            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0x26DFBACCBEFEE267ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterF) ^ 0x1F8ED0A10F3C3D87ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 6U)) & S_SALT1];
