            aWandererA = aWandererA + ((RotL64(aCross, 51U) + aOrbiterG) + RotL64(aOrbiterF, 27U));
            aWandererE = aWandererE ^ ((RotL64(aScatter, 5U) + aOrbiterJ) + RotL64(aOrbiterD, 50U));
            aWandererK = aWandererK + (((RotL64(aIngress, 13U) + RotL64(aOrbiterJ, 3U)) + aOrbiterF) + aTwistWandererUpdateSaltE[(((255U - aIndex) + 94U)) & S_SALT1]);
