            //
            aIngress = (RotL64(aIceLaneD[((aIndex + 6764U)) & S_BLOCK1], 13U) ^ RotL64(aIceLaneB[((aIndex + 6587U)) & S_BLOCK1], 5U));
            aIngress ^= (RotL64(aLightningLaneD[((aIndex + 85U)) & S_BLOCK1], 44U) ^ RotL64(aSoilLaneB[((aIndex + 8010U)) & S_BLOCK1], 29U));
