            //
            aOrbiterK = (aWandererC + RotL64(aScatter, 53U)) + 0x412341E6845D1371ULL;
            aOrbiterG = ((aWandererE + RotL64(aCross, 24U)) + RotL64(aCarry, 41U)) + 0x98AE87DD912C1F61ULL;
            aOrbiterB = (((aWandererA + RotL64(aIngress, 13U)) + RotL64(aCarry, 13U)) + 0xDCB82B0D9D39464CULL) + aTwistOrbiterAssignSaltF[((aIndex + 146U)) & S_SALT1];
            aOrbiterI = (aWandererK + RotL64(aPrevious, 41U)) + 0x59F62A933C99A0CAULL;
            aOrbiterE = (aWandererB + RotL64(aCross, 37U)) + 0x1D9ABCA165BBA4F8ULL;
            aOrbiterC = ((aWandererG + RotL64(aPrevious, 57U)) + RotL64(aCarry, 53U)) + 0xE89EDAF7C77DD4BEULL;
